/bin/bash -lc "python3 - <<'PY'
try:
    import markdown_it
    print('markdown_it', markdown_it.__version__)
except Exception as exc:
    print(type(exc).__name__, exc)
try:
    import markdown
    print('markdown', markdown.__version__)
except Exception as exc:
    print(type(exc).__name__, exc)
try:
    import commonmark
    print('commonmark', getattr(commonmark, '__version__', 'unknown'))
except Exception as exc:
    print(type(exc).__name__, exc)
PY"

